INSERT INTO user_locations (user_id, location_id, start_date, end_date)
SELECT #{userId}, #{locationId}, #{startDate}, #{endDate}
WHERE NOT EXISTS (
    SELECT 1 FROM user_locations
    WHERE user_id = #{userId}
        AND (end_date IS NULL OR end_date > NOW())
)

mapper.select:
SELECT user_id, location_id, start_date, end_date
FROM user_locations
WHERE user_id = #{userId}
    AND location_id = #{locationId}
    AND (end_date IS NULL OR end_date > NOW())

SELECT EXISTS (
    SELECT 1
    FROM user_locations
    WHERE location_id = #{locationId}
        AND (end_date IS NULL OR end_date > NOW())
)

mapper.update:
UPDATE user_locations SET end_date = NOW()
WHERE user_id = #{userId}
    AND location_id = #{locationId}
    AND (end_date IS NULL OR end_date > NOW())
